const wh = $input.first().json || {};
const b = (wh.body && typeof wh.body === 'object') ? wh.body : {};
const S = function (v) { return v == null ? '' : String(v).trim(); };
const name = S(b.name || b.kunde_name);
const email = S(b.email || b.mail);
const telefon = S(b.telefon || b.phone || b.tel);
const ort = S(b.ort || b.plz_ort || b.plz);
const gewerk = S(b.service || b.gewerk || b.leistung || b.betreff);
const nachricht = S(b.nachricht || b.message || b.beschreibung || b.text);
const budget = parseFloat(String(b.budget || '').replace(/[^0-9.]/g, '')) || null;
const utm_source = S(b.utm_source);
const utm_campaign = S(b.utm_campaign);
const utm_term = S(b.utm_term || b.keyword);
const gclid = S(b.gclid);
const seite = S(b.seite || b.page || ((wh.headers || {}).referer) || '');
const honig = S(b.webseite || b.website_url || b.hp);
const spam = !!honig || (!name && !email && !telefon) || (!nachricht && !gewerk);
let h = 0;
const key = (email || telefon || name) + '|' + nachricht.slice(0, 80);
for (let i = 0; i < key.length; i++) { h = (h * 31 + key.charCodeAt(i)) >>> 0; }
const extern_id = 'web-' + h.toString(36) + '-' + key.length;
const titel = ((gewerk ? gewerk + ' - ' : '') + (nachricht ? nachricht.slice(0, 90) : 'Anfrage über die Website')).slice(0, 140);
// NEU (Task 4, Fotoupload): bis zu 3 Fotos aus dem Formular durchreichen, je client-seitig komprimiert.
// Format je Foto: { titel, daten } mit daten = "data:image/...;base64,....".
const fotosIn = Array.isArray(b.fotos) ? b.fotos : [];
const fotos = fotosIn.filter(function (f) {
  return f && typeof f.daten === 'string' && f.daten.length > 0 && f.daten.length < 14000000;
}).slice(0, 3).map(function (f) {
  return { titel: S(f.titel).slice(0, 120), daten: f.daten };
});
return [{ json: { spam: spam, extern_id: extern_id, titel: titel, name: name, email: email, telefon: telefon,
  ort: ort, gewerk: gewerk, nachricht: nachricht, budget: budget,
  utm_source: utm_source, utm_campaign: utm_campaign, utm_term: utm_term, gclid: gclid, seite: seite, fotos: fotos } }];

const r = $input.first().json || {};
const f = $('Felder Lesen').first().json || {};
if (r.ok !== true || r.doppelt === true || !f.email || f.email.indexOf('@') < 0) return [];
const esc = function (s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const html = '<div style="font-family:Arial,sans-serif;color:#1c2733;max-width:560px;font-size:15px;line-height:1.55">'
  + '<p>Guten Tag' + (f.name ? ' ' + esc(f.name) : '') + ',</p>'
  + '<p>vielen Dank für Ihre Anfrage' + (f.gewerk ? ' zu <b>' + esc(f.gewerk) + '</b>' : '') + '. '
  + 'Wir haben sie erhalten (Referenz <b>' + esc(r.nr || '') + '</b>) und melden uns innerhalb von 24 Stunden bei Ihnen.</p>'
  + '<p><b>Tipp:</b> Fotos vom Objekt beschleunigen die Offerte deutlich. '
  + 'Antworten Sie einfach auf diese E-Mail und hängen Sie Fotos oder Pläne an.</p>'
  + '<p style="color:#5c6b7a;font-size:13px">BauStern GmbH · Zürich · <a href="https://baustern.ch" style="color:#b98a2f">baustern.ch</a></p></div>';
return [{ json: { an: f.email, betreff: 'Ihre Anfrage ist bei uns angekommen (' + (r.nr || 'BauStern') + ')', html: html } }];

const r = $input.first().json || {};
const f = $('Felder Lesen').first().json || {};
if (r.ok !== true) return [{ json: { text: 'Website-Anfrage konnte NICHT gespeichert werden: ' + (r.error || '?'), messageThreadId: 0 } }];
if (r.doppelt === true) return [];
// Test-Topic "#60 — Живой тест формы" wurde am 2026-09-09 nach Abschluss des Livetests geloescht.
// Alle Website-Anfragen (auch mit utm_source=test*) gehen jetzt in den Haupt-Chat (Thread 0).
const zeilen = ['Neue Anfrage über die WEBSITE', '',
  f.titel || '',
  (f.name || 'Unbekannt') + ' · ' + (f.telefon || f.email || 'kein Kontakt'),
  f.ort ? 'Ort: ' + f.ort : '',
  f.utm_source ? 'Quelle: ' + f.utm_source + (f.utm_term ? ' / ' + f.utm_term : '') : '',
  '', 'Nummer: ' + (r.nr || '')];
return [{ json: { text: zeilen.filter(function (z) { return z !== ''; }).join('\n'), messageThreadId: 0 } }];

const r = $input.first().json || {};
const f = $('Felder Lesen').first().json || {};
const fotos = Array.isArray(f.fotos) ? f.fotos : [];
if (r.ok !== true || r.doppelt === true || !fotos.length || !r.id) return [];
const approxBytes = function (s) { return Math.round(String(s || '').length * 3 / 4); };
const rows = fotos.map(function (foto, i) {
  return { anfrage_id: r.id, phase: 'vorher', titel: foto.titel || '', daten: foto.daten, bytes: approxBytes(foto.daten), sortierung: i, quelle: 'website' };
});
return [{ json: { rows: rows } }];
